"""
Dummy Cloud — the always-on piece of your assistant.

Deploy this to Render.com (free tier). It runs independently of your laptop:
- Holds reminders & timers
- Checks them in the background and pushes phone alerts via ntfy.sh
- Serves the JSON API + mobile dashboard your phone/KWGT widget reads from

Your laptop's alexa.py talks to this server over the internet whenever you
set a reminder/timer by voice — it doesn't need to stay on for the reminder
to still fire and reach your phone later.
"""

import os
import re
import json
import time
import base64
import logging
import threading
from flask import Flask, jsonify, request, render_template_string, Response

app = Flask(__name__)

# ── Config (set these as environment variables in Render's dashboard) ────────
NTFY_TOPIC = os.environ.get("NTFY_TOPIC", "")            # same topic as your phone's ntfy app
API_SECRET = os.environ.get("API_SECRET", "change-me")   # shared secret so randoms can't spam your reminders

DATA_FILE = "data.json"

reminders = []       # [{"time": "HH:MM", "message": str}]
timers = []          # [{"id": int, "label": str, "end_time": float}]
_next_timer_id = 1
lock = threading.Lock()


# ── Persistence (survives sleep/wake; wiped only on a fresh redeploy) ────────
def load_data():
    global reminders, timers, _next_timer_id
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE) as f:
                d = json.load(f)
            reminders = d.get("reminders", [])
            timers = d.get("timers", [])
            _next_timer_id = d.get("next_timer_id", 1)
        except (json.JSONDecodeError, OSError):
            pass


def save_data():
    with open(DATA_FILE, "w") as f:
        json.dump({"reminders": reminders, "timers": timers, "next_timer_id": _next_timer_id}, f)


# ── Phone push notifications ──────────────────────────────────────────────
def send_phone_alert(title, message):
    if not NTFY_TOPIC:
        return
    import requests
    try:
        requests.post(
            f"https://ntfy.sh/{NTFY_TOPIC}",
            data=message.encode("utf-8"),
            headers={"Title": title, "Priority": "urgent", "Tags": "loudspeaker"},
            timeout=5,
        )
    except requests.exceptions.RequestException as e:
        print(f"ntfy push failed: {e}")


# ── Auth ──────────────────────────────────────────────────────────────────
def check_auth():
    return request.headers.get("X-API-Key") == API_SECRET


# ── Background checker thread ──────────────────────────────────────────────
def checker_loop():
    while True:
        now_str = time.strftime("%H:%M")
        now = time.time()
        with lock:
            due_reminders = [r for r in reminders if r["time"] == now_str]
            for r in due_reminders:
                reminders.remove(r)

            done_timers = [t for t in timers if t["end_time"] <= now]
            for t in done_timers:
                timers.remove(t)

            if due_reminders or done_timers:
                save_data()

        for r in due_reminders:
            send_phone_alert("⏰ Reminder", r["message"])
        for t in done_timers:
            send_phone_alert("⏱️ Timer done", f"{t['label']} is up!")

        time.sleep(20)


# ── API ─────────────────────────────────────────────────────────────────────
@app.route("/api/reminders", methods=["POST"])
def add_reminder():
    if not check_auth():
        return jsonify({"error": "unauthorized"}), 401
    body = request.get_json(force=True)
    time_str = body.get("time", "")
    message = body.get("message", "reminder")
    display_time = body.get("display_time", time_str)  # falls back to raw time if not provided
    if not re.match(r"^\d{2}:\d{2}$", time_str):
        return jsonify({"error": "time must be HH:MM"}), 400
    with lock:
        reminders.append({"time": time_str, "message": message, "display_time": display_time})
        save_data()
    return jsonify({"ok": True})


@app.route("/api/timers", methods=["POST"])
def add_timer():
    global _next_timer_id
    if not check_auth():
        return jsonify({"error": "unauthorized"}), 401
    body = request.get_json(force=True)
    seconds = body.get("seconds")
    label = body.get("label", "Timer")
    if not isinstance(seconds, (int, float)) or seconds <= 0:
        return jsonify({"error": "seconds must be a positive number"}), 400
    with lock:
        timer_id = _next_timer_id
        _next_timer_id += 1
        timers.append({"id": timer_id, "label": label, "end_time": time.time() + seconds})
        save_data()
    return jsonify({"ok": True, "id": timer_id})


def _format_remaining(seconds_left):
    seconds_left = max(0, int(seconds_left))
    mins, secs = divmod(seconds_left, 60)
    hours, mins = divmod(mins, 60)
    if hours:
        return f"{hours}h {mins}m"
    if mins:
        return f"{mins}m {secs}s"
    return f"{secs}s"


@app.route("/api/status")
def api_status():
    """Public read-only status — no auth, so your phone/KWGT can poll it freely."""
    with lock:
        now = time.time()
        rem = [{"time": r.get("display_time", r["time"]), "message": r["message"]} for r in reminders]
        tim = [{"label": t["label"], "remaining": _format_remaining(t["end_time"] - now)} for t in timers]
    return jsonify({"reminders": rem, "timers": tim})


@app.route("/healthz")
def healthz():
    """Hit this from a free keep-alive pinger (e.g. cron-job.org) every ~10 min
    so Render's free tier doesn't spin the service down to sleep."""
    return "ok"


